const languageSelect = document.querySelector("#language");
const toast = document.querySelector("#toast");

function setLanguage(locale) {
  const dictionary = translations[locale] || translations.en;
  document.documentElement.lang = locale;

  document.querySelectorAll("[data-i18n]").forEach((node) => {
    const key = node.dataset.i18n;
    node.textContent = dictionary[key] || translations.en[key] || node.textContent;
  });

  localStorage.setItem("hapens-language", locale);
}

function showScreen(id) {
  document.querySelectorAll(".screen").forEach((screen) => {
    screen.classList.toggle("active", screen.id === id);
  });
  window.scrollTo({ top: 0, behavior: "smooth" });
}

function showToast(messageKey) {
  const dictionary = translations[languageSelect.value] || translations.en;
  toast.textContent = dictionary[messageKey] || translations.en[messageKey];
  toast.classList.add("show");
  window.clearTimeout(showToast.timeout);
  showToast.timeout = window.setTimeout(() => toast.classList.remove("show"), 2400);
}

function field(name) {
  return document.querySelector(`[name="${name}"]`);
}

function copyAddress(fromPrefix, toPrefix) {
  const fields = ["address", "city", "country", "state", "district", "pincode"];
  fields.forEach((part) => {
    const source = field(`${fromPrefix}-${part}`);
    const target = field(`${toPrefix}-${part}`);
    if (source && target) {
      target.value = source.value;
    }
  });
}

